import{c as e,Q as a,j as n,m as i}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"How Anthropic Engineers Actually Prompt Fable 5","description":"","frontmatter":{"url":"https://x.com/nateherk/status/2072431375530008871","title":"How Anthropic Engineers Actually Prompt Fable 5","author":"nateherk","archived":"2026-07-03T00:00:00.000Z","handle":"@nateherk","published":"2026-07-01T00:00:00.000Z","stats":"185 likes · 18 retweets · 424 bookmarks · 155388 views","tags":["fable5","prompting","verification","negative-prompting","effort-levels","reasoning-extraction","cost-optimization","silent-routing"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-07-01-@nateherk-008871.md","filePath":"research/tweets/2026-07-01-@nateherk-008871.md","lastUpdated":1785909234000}'),r={name:"research/tweets/2026-07-01-@nateherk-008871.md"};function s(o,t,l,h,p,g){return a(),n("div",null,[...t[0]||(t[0]=[i(`<h1 id="how-anthropic-engineers-actually-prompt-fable-5-—-nateherk" tabindex="-1">How Anthropic Engineers Actually Prompt Fable 5 — @nateherk <a class="header-anchor" href="#how-anthropic-engineers-actually-prompt-fable-5-—-nateherk" aria-label="Permalink to &quot;How Anthropic Engineers Actually Prompt Fable 5 — @nateherk&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/nateherk/status/2072431375530008871" target="_blank" rel="noreferrer">https://x.com/nateherk/status/2072431375530008871</a><strong>作者</strong>：nateherk（@nateherk） <strong>發布日期</strong>：2026-07-01 <strong>收錄日期</strong>：2026-07-03 <strong>類型</strong>：Twitter Article <strong>統計</strong>：185 likes · 18 retweets · 424 bookmarks · 155388 views</p><hr><h2 id="全文摘要" tabindex="-1">全文摘要 <a class="header-anchor" href="#全文摘要" aria-label="Permalink to &quot;全文摘要&quot;">​</a></h2><p><strong>定位</strong>：基於 Anthropic 官方 prompting guide + 工程師建議的 6 個 Fable 5 使用習慣；附定價資訊和 reasoning_extraction 安全路由警告。</p><h3 id="定價與截止日期" tabindex="-1">定價與截止日期 <a class="header-anchor" href="#定價與截止日期" aria-label="Permalink to &quot;定價與截止日期&quot;">​</a></h3><ul><li>Fable 5：$10/M input, $50/M output（Opus 的 2 倍）</li><li>2026-07-07 前免費促銷期，最多 50% 週配額；之後改用 usage credits</li></ul><h3 id="_6-個習慣" tabindex="-1">6 個習慣 <a class="header-anchor" href="#_6-個習慣" aria-label="Permalink to &quot;6 個習慣&quot;">​</a></h3><p><strong>習慣 1：給出 Why（意圖前置）</strong></p><ul><li>讓 Fable 5 連接任務到正確文件</li><li>範例：「我在做這個更大任務，這是受眾和需求，幫我寫這封 email」</li></ul><p><strong>習慣 2：告訴它不做什麼（Negative Prompting）</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>When I&#39;m describing a problem, the deliverable is your assessment.</span></span>
<span class="line"><span>Report what you find and stop. Don&#39;t fix, send, edit, or delete</span></span>
<span class="line"><span>anything until I say go.</span></span></code></pre></div><p>→ Fable 比以前模型更積極主動，負面提示效果顯著提升</p><p><strong>習慣 3：有足夠資訊就讓它行動</strong></p><ul><li>&quot;When you have enough information to act, then act.&quot;</li><li>Effort 匹配：high=預設 / xhigh=能力敏感 / medium or low=日常</li><li><strong>成本洞察</strong>：Fable 5 low ≈ Opus 4.8 xhigh 成本且更便宜；大多數任務只需 Fable 5 的 10-15%</li></ul><p><strong>習慣 4：讓它證明（驗證建立）</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Before you tell me something is done, point to the result that proves it.</span></span>
<span class="line"><span>Only report work you can show evidence for. If something isn&#39;t verified,</span></span>
<span class="line"><span>say so plainly instead of guessing.</span></span></code></pre></div><p>→ 寫入 skills、agents、CLAUDE.md，不要每次 paste</p><p><strong>習慣 5：停止要求顯示推理過程</strong></p><ul><li>「explain your reasoning」→ 觸發安全分類器 → <strong>靜默路由到 Opus 4.8</strong>（不告訴用戶）</li><li>API 可見模型切換；UI 可能看不出來</li><li>避免方法：不問推理，不給出看起來惡意的請求</li></ul><p><strong>習慣 6：說更少（Say Less, Not More）</strong></p><ul><li>Fable 智能程度已足夠，短指令 + 好環境（context/tools/skills）效果等同詳細規則列表</li><li>「lead with the outcome, keep it simple, and pause only when the work truly needs me」</li></ul><h3 id="silent-routing-靜默路由-機制" tabindex="-1">Silent Routing（靜默路由）機制 <a class="header-anchor" href="#silent-routing-靜默路由-機制" aria-label="Permalink to &quot;Silent Routing（靜默路由）機制&quot;">​</a></h3><ul><li>Fable 5 先做安全分類：hacking / dangerous biology / <strong>asking model to reveal private reasoning</strong> → 路由到 Opus 4.8</li><li><strong>不告知用戶</strong>；API 可見，UI 不可見</li><li>好處：路由到 Opus 時不按 Fable 5 定價</li></ul><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Fable 5 6 個習慣（基於 Anthropic 官方建議）：Give Why / Negative Prompting / Act When Ready / Prove It / Stop Showing Reasoning / Say Less。關鍵洞察：Fable 5 low ≈ Opus 4.8 xhigh 成本，大多數任務只需 10-15% 使用 Fable；靜默路由到 Opus 不告知用戶。內容與 wquguru/0xMoysei/cyrilXBT 高度重疊。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li><strong>10-15% Fable 使用率</strong>：Fable low ≈ Opus xhigh，大部分任務不需要 Fable 5</li><li><strong>Silent Routing</strong>：Fable 路由到 Opus 不告知用戶；API 可見，UI 不可見</li><li><strong>「Say Less」反直覺</strong>：智能環境下短指令 = 詳細規則清單效果</li><li><strong>驗證習慣建入系統</strong>：不是每次 paste，而是寫入 skills/agents/CLAUDE.md</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>Fable 5 定價：$10/M input, $50/M output</li><li>促銷截止：2026-07-07（50% 週配額）</li><li>Fable 5 low ≈ Opus 4.8 xhigh（成本比較）</li><li>Silent routing：觸發域（hacking/biology/reasoning extraction）</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>與 wquguru（8.6）、cyrilXBT（8.7）、0xMoysei（7.4）高度重疊（驗證塊/reasoning_extraction/negative prompting）</li><li>「Say Less, Not More」是本批次較少見的反直覺觀點</li><li>「10-15% Fable 使用率」量化成本指導有實用性，其他文章較少見</li><li>Silent routing「API 可見，UI 不可見」細節是有用的補充</li><li>文章較短（6325 字），缺乏深度技術細節；更像入門摘要</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>6/10</td><td>驗證塊和 negative prompting 模板可用；但與已收錄文章高度重疊</td></tr><tr><td>B. 創新性 (20%)</td><td>5/10</td><td>高重疊；「10-15%」量化和「Say Less」是邊際新增；無新框架</td></tr><tr><td>C. 證據品質 (20%)</td><td>6.5/10</td><td>引用 Anthropic 官方建議；cost 比較有實用性；無具體實驗數據</td></tr><tr><td>D. 技術深度 (15%)</td><td>5.5/10</td><td>文章較短；6 習慣缺乏實作細節；Silent routing 機制描述清楚</td></tr><tr><td>E. 泛化性 (15%)</td><td>7/10</td><td>習慣 1-4 和 6 跨模型適用</td></tr><tr><td><strong>加權總分</strong></td><td><strong>6.0/10</strong></td><td>6×0.3+5×0.2+6.5×0.2+5.5×0.15+7×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Others <strong>理由</strong>：主要洞察（驗證塊/reasoning_extraction/negative prompting）已由 wquguru/cyrilXBT/0xMoysei 更完整覆蓋；「10-15% Fable 使用率」和「Say Less」是邊際增量，不足以單獨整合；Silent routing UI/API 差異可作參考但無規則層面行動項。</p>`,37)])])}const c=e(r,[["render",s]]);export{u as __pageData,c as default};
